"""Lot 0.130.0: the land-use census counts a street's Empties (`blockers`) as built land -- the walker's walk of cold
run 9386, finding 7 (the factory's `docs/findings/walk_2026-10-23_9386/landuse/`).

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * site_landuse.py -- `census` paints `blockers` as building.
  * tests/test_landuse_blockers.py -- new.
  * VERSION Lot 0.129.0 -> Lot 0.130.0, CHANGELOG.

Generated by `patches/lot_landuse_blockers/gen_lot_landuse_blockers.py` from a proven clone.

    python patches/patch_lot_landuse_blockers.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "lot"
PINS = {'site_landuse.py': 'eb8b8b87fb35a5fc'}
EDITS = {'site_landuse.py': [('lines 17-17', '    rotated_footprint`);\n', "    rotated_footprint`), and an EMPTY's: a `blockers` entry, its `size_x` by\n    `size_y` (0.130.0);\n"), ('lines 154-155', '            _paint(grid, rect, r, lambda x, y: True, "building")\n    slabs = [s for s in site_surfaces.tops(site_spec, ground=ext) if s["family"] != "ground"]\n', '            _paint(grid, rect, r, lambda x, y: True, "building")\n    # AN EMPTY IS BUILT LAND (0.130.0). The walker, walking cold run 9386, of\n    # broad ground round restaurant_row_001: "this empty space goes against\n    # the doc i sent you about the value of urban land". Measuring it found\n    # this census wrong first: a street\'s Empties are the spec\'s `blockers`,\n    # never painted, so a row of 26 rowhomes read as remainder -- 58.4 %\n    # where 47.7 % is unclaimed (the factory\'s\n    # `docs/findings/walk_2026-10-23_9386/landuse/`). Painted as building\n    # land here, after the buildings and before the ground, so a cell takes\n    # its first use as before. Not in `buildings`: separation and the\n    # building line stay about the buildings a mission enters, as before.\n    for bl in site_spec.get("blockers", []) or []:\n        if "size_x" not in bl or "size_y" not in bl:\n            continue\n        r = site_extent.rotated_footprint(dict(bl, footprint=[bl["size_x"], bl["size_y"]]))\n        if r is not None:\n            _paint(grid, rect, r, lambda x, y: True, "building")\n    slabs = [s for s in site_surfaces.tops(site_spec, ground=ext) if s["family"] != "ground"]\n')]}
NEW_FILES = {'tests/test_landuse_blockers.py': '"""The census counts an Empty as built land (0.130.0): a `blockers` entry\'s footprint is `building`, not remainder.\nThe walker, walking cold run 9386: "this empty space goes against the doc i sent you about the value of urban land"\n-- and restaurant_row_001\'s 26 rowhomes had read as remainder. FAILS ON 0.129.0."""\nimport site_landuse\n\n\ndef _spec(blockers):\n    return {"ground": {"size_x": 40, "size_y": 20}, "buildings": [], "roads": [], "paths": [],\n            "blockers": blockers}\n\n\ndef _as_building(bl):\n    """The same footprint as a mission\'s building: what the census has always measured a building\'s land as, its\n    0.5 m cells included at the edges."""\n    s = _spec([])\n    s["buildings"] = [{"id": "b0", "at": bl["at"], "rot": bl["rot"], "footprint": [bl["size_x"], bl["size_y"]]}]\n    return site_landuse.census(s)\n\n\ndef test_an_empty_is_building_land_not_remainder():\n    bl = {"id": "e0", "at": [5.0, 0.0], "rot": 180, "size_x": 6.0, "size_y": 12.0}\n    bare = site_landuse.census(_spec([]))\n    one = site_landuse.census(_spec([bl]))\n    assert bare["ok"] and one["ok"], (bare, one)\n    assert bare["areas"]["building"] == 0.0\n    assert one["areas"]["building"] == _as_building(bl)["areas"]["building"] > 0.0, one["areas"]\n    assert one["areas"]["remainder"] == bare["areas"]["remainder"] - one["areas"]["building"]\n\n\ndef test_an_empty_turned_a_quarter_is_measured_turned():\n    bl = {"id": "e0", "at": [0.0, 0.0], "rot": 90, "size_x": 6.0, "size_y": 12.0}\n    assert site_landuse.census(_spec([bl]))["areas"]["building"] == _as_building(bl)["areas"]["building"]\n\n\ndef test_an_empty_is_not_a_building_the_mission_enters():\n    c = site_landuse.census(_spec([{"id": "e0", "at": [5.0, 0.0], "rot": 0, "size_x": 6.0, "size_y": 12.0}]))\n    assert c["nearest_building_gap"] == {}, c["nearest_building_gap"]\n'}
CHANGELOG = '## 0.130.0 - the land-use census counts a street\'s Empties as built land\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 7), of broad ground\nround restaurant_row_001: "this empty space goes against the doc i sent you about the value of urban land", and "its\nok for levels to have open areas but it should be with intention and to support gameplay not just because we forgot to\nput something there". Measuring where that ground is found this census wrong first: it painted `buildings` only, and a\nstreet\'s Empties are the spec\'s `blockers`, so restaurant_row_001\'s row of 26 rowhomes read as remainder -- 58.4 % of\nthe plate where 47.7 % is unclaimed (cold run 9391\'s site, the factory\'s\n`docs/findings/walk_2026-10-23_9386/landuse/remainder_map.py`).\n\n### Changed\n- **`site_landuse.census`** paints each `blockers` entry\'s footprint (`size_x` by `size_y`, turned by its `rot`) as\n  `building`, after the buildings and before the ground. Not added to `buildings`: separation and the building line\n  stay about the buildings a mission enters. Every land-use figure since 0.93.0 overstated the remainder on a site\n  with an Empty row; the census is a measurement and gates nothing, so no site changes.\n\n### Tests\n- `tests/test_landuse_blockers.py` (new): an Empty\'s land is building land, measured as a building of its footprint\n  is, turned or not; it is not a building a mission enters. The first two fail on 0.129.0.\n\n'
OLD_VERSION, NEW_VERSION = 'Lot 0.129.0', 'Lot 0.130.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: lot/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: lot/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: lot/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: lot/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## " + OLD_VERSION.split()[-1].encode() + b" "):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in lot/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
